BEGIN;
DO $test$
DECLARE field jsonb:=$field$[{"id": "002", "name": "JARVIS ZEBRAS"}, {"id": "020", "name": "SAUCE FC"}, {"id": "021", "name": "ALASKAN BULL WORMS"}, {"id": "022", "name": "BC UNITED ZEBRAS"}, {"id": "026", "name": "GIVE US WANG"}, {"id": "030", "name": "NANISTATE"}, {"id": "041", "name": "HARVEY FREKES"}, {"id": "050", "name": "VICTORYRULES"}, {"id": "056", "name": "BIG MAC FC"}, {"id": "069", "name": "SILVERMAN'S XI"}, {"id": "075", "name": "AFC BIG RED PORT"}, {"id": "085", "name": "FULLY SCICLUNA"}]$field$; groups jsonb:=$groups${"A": ["AFC BIG RED PORT", "JARVIS ZEBRAS", "BC UNITED ZEBRAS", "HARVEY FREKES"], "B": ["SILVERMAN'S XI", "SAUCE FC", "GIVE US WANG"], "C": ["FULLY SCICLUNA", "ALASKAN BULL WORMS", "NANISTATE"]}$groups$; quotes jsonb:=$quotes$[{"id": "ECLGROUP|A|AFC BIG RED PORT", "team": "AFC BIG RED PORT", "team_id": "075", "odds": 3.5, "baseOdds": 3.5, "prices": [3.5], "type": "ECLGROUP", "category": "ECLGROUP|A", "exclusive": "ECLGROUP|A", "round": 13, "safetyGroup": "ECLGROUP|A", "safetyOutcome": "AFC BIG RED PORT", "safetySize": 4, "eclModelVersion": "ecl-three-matchdays-v1", "eclFingerprint": "isolated-test"}, {"id": "ECLGROUP|A|JARVIS ZEBRAS", "team": "JARVIS ZEBRAS", "team_id": "002", "odds": 3.5, "baseOdds": 3.5, "prices": [3.5], "type": "ECLGROUP", "category": "ECLGROUP|A", "exclusive": "ECLGROUP|A", "round": 13, "safetyGroup": "ECLGROUP|A", "safetyOutcome": "JARVIS ZEBRAS", "safetySize": 4, "eclModelVersion": "ecl-three-matchdays-v1", "eclFingerprint": "isolated-test"}, {"id": "ECLGROUP|A|BC UNITED ZEBRAS", "team": "BC UNITED ZEBRAS", "team_id": "022", "odds": 3.5, "baseOdds": 3.5, "prices": [3.5], "type": "ECLGROUP", "category": "ECLGROUP|A", "exclusive": "ECLGROUP|A", "round": 13, "safetyGroup": "ECLGROUP|A", "safetyOutcome": "BC UNITED ZEBRAS", "safetySize": 4, "eclModelVersion": "ecl-three-matchdays-v1", "eclFingerprint": "isolated-test"}, {"id": "ECLGROUP|A|HARVEY FREKES", "team": "HARVEY FREKES", "team_id": "041", "odds": 3.5, "baseOdds": 3.5, "prices": [3.5], "type": "ECLGROUP", "category": "ECLGROUP|A", "exclusive": "ECLGROUP|A", "round": 13, "safetyGroup": "ECLGROUP|A", "safetyOutcome": "HARVEY FREKES", "safetySize": 4, "eclModelVersion": "ecl-three-matchdays-v1", "eclFingerprint": "isolated-test"}]$quotes$;
 before_groups jsonb; response jsonb; other_hash text; financial_hash text; failed boolean; bad jsonb;
BEGIN
 IF NOT public.bilbbet_ecl_draw_view() ?& ARRAY['groups','quotes','fixtures','paused_categories'] THEN RAISE EXCEPTION 'Public draw view unavailable'; END IF;
 BEGIN PERFORM public.bilbbet_commit_ecl_draw(groups,quotes,field,'{}'); RAISE EXCEPTION 'Anonymous write was allowed';
 EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE '%Administrator sign-in required%' THEN RAISE; END IF; END;
 INSERT INTO bilbbet_private.credentials(username,administrator) VALUES('__ecl_draw_test_admin_20261111__',true);
 INSERT INTO public.kv_store(key,value) VALUES('bilbbet2_user:__ecl_draw_test_admin_20261111__','{"username":"__ecl_draw_test_admin_20261111__","status":"APPROVED","balance":0}');
 INSERT INTO bilbbet_private.sessions(token_hash,username,expires_at) VALUES(encode(extensions.digest('__ecl_draw_test_token_20261111__','sha256'),'hex'),'__ecl_draw_test_admin_20261111__',now()+interval '1 minute');
 PERFORM set_config('request.headers','{"x-bilbbet-session":"__ecl_draw_test_token_20261111__"}',true);
 SELECT coalesce(value,'{"A":[],"B":[],"C":[]}') INTO before_groups FROM public.kv_store WHERE key='bilbbet2_ecl_groups';
 before_groups:=coalesce(before_groups,'{"A":[],"B":[],"C":[]}');
 SELECT md5(string_agg(id||value::text,'' ORDER BY id)) INTO other_hash FROM bilbbet_private.quotes WHERE id NOT LIKE 'ECLGROUP|%';
 SELECT md5(string_agg(key||value::text,'' ORDER BY key)) INTO financial_hash FROM public.kv_store WHERE key LIKE 'bilbbet2_user:%' OR key LIKE 'bilbbet2_bet:%' OR key LIKE 'bilbbet2_tx:%';
 bad:=jsonb_set(groups,'{B,1}',groups#>'{A,1}');failed:=false;
 BEGIN PERFORM public.bilbbet_commit_ecl_draw(bad,quotes,field,before_groups); EXCEPTION WHEN OTHERS THEN failed:=true; END;
 IF NOT failed THEN RAISE EXCEPTION 'Duplicate was accepted'; END IF;
 bad:=jsonb_set(groups,'{A,0}',groups#>'{A,1}');failed:=false;
 BEGIN PERFORM public.bilbbet_commit_ecl_draw(bad,quotes,field,before_groups); EXCEPTION WHEN OTHERS THEN failed:=true; END;
 IF NOT failed THEN RAISE EXCEPTION 'Invalid pot/slot was accepted'; END IF;
 SELECT jsonb_agg(q||'{"prices":[10],"odds":10}'::jsonb) INTO bad FROM jsonb_array_elements(quotes) q;failed:=false;
 BEGIN PERFORM public.bilbbet_commit_ecl_draw(groups,bad,field,before_groups); EXCEPTION WHEN OTHERS THEN failed:=true; END;
 IF NOT failed THEN RAISE EXCEPTION 'Arbitrage book was accepted'; END IF;
 response:=public.bilbbet_commit_ecl_draw(groups,quotes,field,before_groups);
 IF (response->>'quotes')::integer<>4 OR response->'published_groups'<>'["A"]'::jsonb THEN RAISE EXCEPTION 'Complete group was not published'; END IF;
 IF (SELECT count(*) FROM bilbbet_private.quotes WHERE id LIKE 'ECLGROUP|%')<>4 THEN RAISE EXCEPTION 'Incomplete groups received quotes'; END IF;
 IF jsonb_array_length(public.bilbbet_ecl_draw_view()->'quotes')<>4 THEN RAISE EXCEPTION 'Public draw view leaked unrelated quotes'; END IF;
 failed:=false;BEGIN PERFORM public.bilbbet_commit_ecl_draw(groups,quotes,field,before_groups); EXCEPTION WHEN OTHERS THEN failed:=true; END;
 IF NOT failed THEN RAISE EXCEPTION 'Stale concurrent draw was accepted'; END IF;
 UPDATE public.kv_store SET value=jsonb_set(value,'{ECL|win_pct}','false') WHERE key='bilbbet2_paused_categories';
 PERFORM public.bilbbet_commit_ecl_draw(groups,quotes,field,groups);
 IF (SELECT (value->>'ECL|win_pct')::boolean FROM public.kv_store WHERE key='bilbbet2_paused_categories') IS DISTINCT FROM false THEN RAISE EXCEPTION 'Unchanged draw retry reset reviewed stage controls'; END IF;
 IF (SELECT md5(string_agg(id||value::text,'' ORDER BY id)) FROM bilbbet_private.quotes WHERE id NOT LIKE 'ECLGROUP|%') IS DISTINCT FROM other_hash THEN RAISE EXCEPTION 'Other price books changed'; END IF;
 IF (SELECT md5(string_agg(key||value::text,'' ORDER BY key)) FROM public.kv_store WHERE key LIKE 'bilbbet2_user:%' OR key LIKE 'bilbbet2_bet:%' OR key LIKE 'bilbbet2_tx:%') IS DISTINCT FROM financial_hash THEN RAISE EXCEPTION 'Financial records changed'; END IF;
 bad:=jsonb_set(groups,'{A,1}','null');PERFORM public.bilbbet_commit_ecl_draw(bad,'[]',field,groups);
 IF EXISTS(SELECT 1 FROM bilbbet_private.quotes WHERE id LIKE 'ECLGROUP|%') THEN RAISE EXCEPTION 'Corrected incomplete group retained old prices'; END IF;
END $test$;
ROLLBACK;
SELECT true AS isolated_ecl_draw_tests_passed;
